package fixture;
import java.util.*;import net.flashlight.battery.Power;import net.minecraft.world.item.*;import net.minecraft.resources.*;import net.minecraft.world.*;import net.minecraft.network.chat.Component;
public class Checks{
 static int checks;static void ok(boolean b,String msg){checks++;if(!b)throw new AssertionError(msg);}static ItemStack s(String id){return new ItemStack(ResourceLocation.parse(id),1);}
 public static class World{public boolean isClientSide;public int sounds;public void playSound(Object p,Object pos,Object sound,Object source,float v,float pitch){sounds++;}}
 public static class Inv{public ItemStack[] stacks=new ItemStack[36];public int dirty;Inv(){Arrays.setAll(stacks,i->s("minecraft:air"));for(ItemStack s:stacks)s.shrink(1);}public ItemStack getItem(int i){return stacks[i];}public void setChanged(){dirty++;}public boolean add(ItemStack s){for(int i=0;i<36;i++)if(stacks[i].isEmpty()){stacks[i]=s.copy();s.shrink(s.getCount());return true;}return false;}}
 public static class Player{public World world=new World();public Inv inv=new Inv();public boolean shift;public ItemStack main=s("minecraft:air"),off=s("minecraft:air");public List<Component> messages=new ArrayList<>();public int drops;public World level(){return world;}public Object blockPosition(){return this;}public Inv getInventory(){return inv;}public ItemStack getOffhandItem(){return off;}public ItemStack getMainHandItem(){return main;}public ItemStack getItemInHand(InteractionHand h){return h==InteractionHand.MAIN_HAND?main:off;}public void setItemInHand(InteractionHand h,ItemStack s){if(h==InteractionHand.MAIN_HAND)main=s;else off=s;}public boolean isShiftKeyDown(){return shift;}public void displayClientMessage(Component c,boolean action){messages.add(c);}public void drop(ItemStack s,boolean random){drops++;}}
 static String id(ItemStack s){return s.item.toString();}
 public static void main(String[]args){
  for(int tier=0;tier<4;tier++){
   String name=Power.TYPES[tier];Player p=new Player();p.main=s("flashlight:"+name+"_off");ok(Power.remaining(p.main)==0,"crafted light starts empty");Power.click(p,p.main);ok(id(p.main).endsWith("_off")&&p.messages.getLast().key().contains("no_battery"),"no free battery");p.inv.stacks[3]=s("flashlight:battery");Power.click(p,p.main);ok(id(p.main).equals("flashlight:"+name)&&p.inv.stacks[3].isEmpty(),"activation consumes exactly one battery");ok(Power.remaining(p.main)==Power.CAPACITY[tier],"tier charge");ok(Power.range(p)==Power.RANGE[tier],"tier beam range");ok(Power.width(p.main)==13,"full battery bar");
   Power.tick(p);ok(Power.remaining(p.main)==Power.CAPACITY[tier]-1,"one lit tick consumption");Power.click(p,p.main);int n=Power.remaining(p.main);for(int i=0;i<100;i++)Power.tick(p);ok(Power.remaining(p.main)==n,"off light pauses drain");Power.click(p,p.main);ok(Power.remaining(p.main)==n,"toggle preserves custom data");
   ItemStack saved=p.main.copy();Player next=new Player();next.off=saved;Power.tick(next);ok(Power.remaining(next.off)==n-1,"charge follows transferred stack");
   Power.charge(p.main,1201);Power.tick(p);ok(p.messages.getLast().key().endsWith("low"),"low battery warning");Power.charge(p.main,1);Power.tick(p);ok(id(p.main).endsWith("_off")&&Power.remaining(p.main)==0,"auto off exactly at zero");ok(Power.range(p)==0,"empty gives no beam");Power.click(p,p.main);ok(id(p.main).endsWith("_off"),"cannot reactivate empty without battery");
   p.inv.stacks[4]=s("flashlight:battery");p.shift=true;Power.click(p,p.main);ok(Power.remaining(p.main)==Power.CAPACITY[tier]&&id(p.main).endsWith("_off"),"manual recharge preserves off state");p.inv.stacks[4]=s("flashlight:battery");Power.click(p,p.main);ok(p.inv.stacks[4].getCount()==1,"full charge does not waste battery");
   ArrayList<Object> tooltip=new ArrayList<>();Power.tooltip(p.main,tooltip);ok(tooltip.size()==2,"charge and controls tooltip");
   p.shift=false;Power.click(p,p.main);int full=Power.remaining(p.main);for(int i=0;i<full;i++)Power.tick(p);ok(id(p.main).endsWith("_off"),"full capacity expires after exact tier tick count");
  }
  Player client=new Player();client.world.isClientSide=true;client.main=s("flashlight:flashlight");Power.charge(client.main,42);Power.tick(client);Power.click(client,client.main);ok(Power.remaining(client.main)==42&&id(client.main).equals("flashlight:flashlight"),"server authoritative");
  Player dual=new Player();dual.main=s("flashlight:flashlight");dual.off=s("flashlight:tactical");Power.charge(dual.main,100);Power.charge(dual.off,200);Power.click(dual,dual.main);ok(id(dual.off).equals("flashlight:tactical")&&Power.remaining(dual.off)==200,"toggle never changes other hand");Power.tick(dual);ok(Power.remaining(dual.main)==100&&Power.remaining(dual.off)==199,"only lit hand drains");
  Player start=new Player();start.off=s("minecraft:shield");start.inv.stacks[1]=s("flashlight:flashlight_off");Power.starter(start);ok(Power.remaining(start.off)==12000&&id(start.off).equals("flashlight:flashlight"),"starter lit with full battery");ok(Arrays.stream(start.inv.stacks).anyMatch(s->id(s).equals("minecraft:shield")),"starter preserves displaced offhand gear");ok(start.inv.stacks[1].isEmpty(),"starter consumes earlier starter flashlight instead of duplicating");
  System.out.println("FLASHLIGHT_BATTERY_CHECKS="+checks);
 }
}
